<div class="card"><h3>Notification center</h3><?php $notifications=rows('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 100',[$user['id']]);foreach($notifications as $n):?><div class="issue row between"><div><a href="<?=url($n['path'])?>"><?=e($n['message'])?></a><p class="small"><?=e($n['created_at'])?></p></div><?php if(!$n['read_at']):?><button class="button secondary small-button" data-action="notification-read" data-id="<?=$n['id']?>">Mark read</button><?php endif;?></div><?php endforeach;if(!$notifications)empty_state('You’re all caught up.','Audit, report, and project updates will appear here.');?></div>
